rss.channel:
{{ site.site_name|default:"Blog" }}
{% firstof site.seo_description site.tagline "" %}
{{ site_url }}/
{% for post in posts %}

  {{ post.title }}
  {{ site_url }}{{ post.get_absolute_url }}
  {{ site_url }}{{ post.get_absolute_url }}
  {% if post.excerpt %}{{ post.excerpt }}{% endif %}
  {% if post.published_at %}{{ post.published_at|date:"r" }}{% endif %}

{% endfor %}
